def flood_fill_brute(image, sr, sc, color):
    old_color = image[sr][sc]
    if old_color == color:
        return image
    image[sr][sc] = color
    changed = True
    while changed:
        changed = False
        for r in range(len(image)):
            for c in range(len(image[0])):
                if image[r][c] == color:
                    for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                        nr, nc = r+dr, c+dc
                        if 0<=nr<len(image) and 0<=nc<len(image[0]) and image[nr][nc]==old_color:
                            image[nr][nc] = color                    # repeated full scans
                            changed = True
    return image

