def flood_fill(image, sr, sc, color):
    old_color = image[sr][sc]
    if old_color == color:
        return image                                        # avoid infinite recursion
    rows, cols = len(image), len(image[0])
    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or image[r][c] != old_color:
            return                                              # out of bounds or wrong color
        image[r][c] = color
        dfs(r + 1, c); dfs(r - 1, c); dfs(r, c + 1); dfs(r, c - 1)  # spread to 4 neighbors
    dfs(sr, sc)
    return image

