public class Main {
    static int[][] floodFill(int[][] image, int sr, int sc, int color) {
        int oldColor = image[sr][sc];
        if (oldColor == color) return image;                       // avoid infinite recursion
        dfs(image, sr, sc, oldColor, color);
        return image;
    }

    static void dfs(int[][] image, int r, int c, int oldColor, int color) {
        if (r < 0 || r >= image.length || c < 0 || c >= image[0].length || image[r][c] != oldColor) return;
        image[r][c] = color;
        dfs(image, r + 1, c, oldColor, color);                        // spread to 4 neighbors
        dfs(image, r - 1, c, oldColor, color);
        dfs(image, r, c + 1, oldColor, color);
        dfs(image, r, c - 1, oldColor, color);
    }
}

