void dfs(vector<vector<int>>& image, int r, int c, int oldColor, int color) {
    if (r < 0 || r >= (int)image.size() || c < 0 || c >= (int)image[0].size() || image[r][c] != oldColor) return;
    image[r][c] = color;
    dfs(image, r + 1, c, oldColor, color);                            // spread to 4 neighbors
    dfs(image, r - 1, c, oldColor, color);
    dfs(image, r, c + 1, oldColor, color);
    dfs(image, r, c - 1, oldColor, color);
}

